.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #fafafa;
    border-left: 1px solid #ddd;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #ddd;
    flex-shrink: 0;
